const fs = require('fs');
const path = '/srv/n8n_v2/json/output.json';

// heurystyczne markery do odcinania stopki
const FOOTER_MARKERS = [
  'Ergosystem Oferujemy wysokiej klasy',
  'Dane Firmy ERGOSYSTEM',
  'Kategorie Meble pracownicze'
];

// prosta funkcja czyszcząca stopkę
function trimFooter(text) {
  let idx = -1;
  for (const marker of FOOTER_MARKERS) {
    const pos = text.indexOf(marker);
    if (pos !== -1) {
      if (idx === -1 || pos < idx) idx = pos;
    }
  }
  if (idx !== -1) {
    return text.slice(0, idx).trim();
  }
  return text.trim();
}

function cleanText(text) {
  if (!text) return '';
  return String(text)
    .replace(/\s+/g, ' ')
    .replace(/\u00a0/g, ' ')
    .trim();
}

function chunkText(text, size) {
  const chunks = [];
  if (!text || !text.trim()) return chunks;
  for (let i = 0; i < text.length; i += size) {
    const chunk = text.slice(i, i + size).trim();
    if (chunk.length > 0) {
      chunks.push(chunk);
    }
  }
  return chunks;
}

// wczytanie pliku JSON
let raw;
try {
  raw = fs.readFileSync(path, 'utf8');
} catch (e) {
  throw new Error(`Nie udało się odczytać pliku ${path}: ${e.message}`);
}

let docs;
try {
  docs = JSON.parse(raw);
} catch (e) {
  throw new Error(`Nie udało się sparsować JSON z ${path}: ${e.message}`);
}

if (!Array.isArray(docs)) {
  throw new Error('output.json nie jest tablicą dokumentów');
}

// jedno pytanie (userMessage) z poprzedniego node'a
const userMessage = items[0].json.userMessage || '';

const MAX_DOCS = 200; // limit bezpieczeństwa
const CHUNK_SIZE = 1200; // ~1200 znaków

const out = [];

for (let i = 0; i < docs.length && i < MAX_DOCS; i++) {
  const d = docs[i];
  const url = d.url || d.link || '';
  const title = d.title || '';
  const body = d.body_text || d.body || d.cleanedText || '';

  let text = cleanText(body);
  text = trimFooter(text);

  if (!text || text.length < 50) continue; // odetnij śmieci

  const chunks = chunkText(text, CHUNK_SIZE);

  chunks.forEach((chunkText, idx) => {
    out.push({
      json: {
        userMessage,
        docId: i,
        chunkIndex: idx,
        chunkId: `${i}::${idx}`,
        url,
        title,
        chunkText
      }
    });
  });
}

if (out.length === 0) {
  // nadal zwróć choć jeden item, żeby agent miał co robić
  return [{ json: { userMessage, selectedContext: '', note: 'Brak chunków z output.json' } }];
}

return out;

// Prosty pseudo-embedding: TF na słowach + cosinus

function tokenize(text) {
  return String(text)
    .toLowerCase()
    .replace(/[^\p{L}\p{N} ]+/gu, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

function tfVector(tokens) {
  const freq = new Map();
  tokens.forEach(t => {
    freq.set(t, (freq.get(t) || 0) + 1);
  });
  return freq;
}

function cosineSim(v1, v2) {
  let dot = 0;
  let norm1 = 0;
  let norm2 = 0;

  for (const [k, v] of v1.entries()) {
    norm1 += v * v;
    if (v2.has(k)) {
      dot += v * v2.get(k);
    }
  }
  for (const v of v2.values()) {
    norm2 += v * v;
  }
  if (!norm1 || !norm2) return 0;
  return dot / (Math.sqrt(norm1) * Math.sqrt(norm2));
}

if (!items.length) {
  return items;
}

const userMessage = items[0].json.userMessage || '';
const qTokens = tokenize(userMessage);
const qVec = tfVector(qTokens);

const scored = items.map(it => {
  const tokens = tokenize(it.json.chunkText || '');
  const vec = tfVector(tokens);
  const score = cosineSim(qVec, vec);
  return { ...it, score };
});

// sortuj malejąco po score
scored.sort((a, b) => b.score - a.score);

const K = 5; // top-k chunków
const top = scored.slice(0, K);

// sklej kontekst w jeden item
const contextParts = top.map(it => {
  const meta = `[${it.json.title || ''}] (${it.json.url || ''})`;
  return `${meta}\n${it.json.chunkText}`;
});

const selectedContext = contextParts.join('\n\n---\n\n');

return [
  {
    json: {
      userMessage,
      selectedContext,
      debug: {
        topScores: top.map(t => ({
          chunkId: t.json.chunkId,
          score: t.score,
          url: t.json.url,
          title: t.json.title
        }))
      }
    }
  }
];
